def compute(vars):
    fy2019_total = vars["v1"]
    fy2018_total = vars["v2"]
    difference = fy2019_total - fy2018_total

    return {
        "value": difference,
        "trace": {
            "fy2019_total": fy2019_total,
            "fy2018_total": fy2018_total,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
